@startuml

class Employee {
  + idNumber : string
  + name : string
  + address : string
}

class AssemblyService {
  + kmsAtTime : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + name : string
  + idNumber : string
  + address : string
  + phone : string
}

Car "1" -- "*" AssemblyService : undergoes
Employee "1" -- "*" AssemblyService : responsibleFor
AssemblyService "*" -- "*" PartAccessory : includes
PartAccessory "*" -- "*" Car : fitsIn
Owner "1" -- "*" Car : owns

@enduml

